"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["97322"],{65430(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.grafo_dependencia_conjunta.grafo_conjunto_com_ciclo","status":422,"titulo":"O grafo de depend\xeancia conjunto (produ\xe7\xe3o, pr\xe9-condi\xe7\xe3o, deriva\xe7\xe3o e gatilho) forma um ciclo"},"descricao":{"codigo":"uniplus.selecao.grafo_dependencia_conjunta.grafo_conjunto_com_ciclo","requisitos":["UNI-REQ-0077","UNI-REQ-0078"],"oQueAconteceu":["A ordem de coleta do processo decorre de um grafo de depend\xeancia que re\xfane\\nquatro tipos de liga\xe7\xe3o entre fatos, campos, etapas, termos exigidos no\\nformul\xe1rio e exig\xeancias (UNI-REQ-0077): a produ\xe7\xe3o (o campo que produz o fato),\\na pr\xe9-condi\xe7\xe3o (as regras de exibi\xe7\xe3o, de obrigatoriedade e de op\xe7\xf5es), a\\nderiva\xe7\xe3o (os fatos de que uma regra de deriva\xe7\xe3o depende) e o gatilho (o fato\\nque dispara a exig\xeancia de documento). Esse grafo precisa ser ac\xedclico, e a\\npublica\xe7\xe3o recusa o ciclo (UNI-REQ-0078).","As liga\xe7\xf5es configuradas do processo formam um ciclo: um dos elementos depende,\\ndireta ou indiretamente, dele mesmo, e n\xe3o h\xe1 ordem em que a coleta possa\\ncome\xe7ar. A mensagem do erro traz o caminho do ciclo, com a etiqueta de cada n\xf3\\n(o tipo do n\xf3 e o c\xf3digo dele), na ordem em que um depende do seguinte. A\\nrecusa sai com **422**, antes de gerar a vers\xe3o, e nada \xe9 congelado.","A consulta de conformidade do processo aponta o mesmo problema no item de\\ngrafo de depend\xeancia sem ciclo, mas apenas como pend\xeancia do checklist; este\\nerro \xe9 o da opera\xe7\xe3o que tenta congelar a configura\xe7\xe3o."],"comoResolver":["Rompa o ciclo em um dos pontos do caminho indicado na mensagem. Conforme a\\nliga\xe7\xe3o que fecha o ciclo:","- retire ou ajuste a pr\xe9-condi\xe7\xe3o que faz um campo ou etapa depender de um fato\\n  que s\xf3 \xe9 produzido nele ou depois dele;\\n- ajuste a regra de deriva\xe7\xe3o para que o fato derivado n\xe3o dependa, direta ou\\n  indiretamente, do pr\xf3prio fato;\\n- se o caminho passa por um gatilho de exig\xeancia de documento, ajuste o\\n  gatilho ou o fato que ele cita.","Em processo j\xe1 publicado, fa\xe7a o ajuste numa retifica\xe7\xe3o e repita a opera\xe7\xe3o\\nrecusada."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Grafo dependencia conjunta"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);